      PropertyReader.setOverrides({
        'GITLAB_BASE_PATH': 'http://127.0.0.1:${server.port}',
        'GITLAB_TOKEN': 'glpat-testtoken',
      });
      dispatcher = SyncToolDispatcher(PropertyReader());
    });

